[Form]
public class NDXBoxItemOutOfVersionFormulaPart extends FormRun
{
    UnitOfMeasureConversion lUintOfMeasureConversion;

}

public void linkActive()
{
    this.query().dataSourceTable(tableNum(NDXUnitItemMapping)).clearRanges();
    if(element.args() != null && element.args().dataset() == tableNum(UnitOfMeasureConversion) && element.args().record() != null)
    {
        lUintOfMeasureConversion = element.args().record();
        this.query().dataSourceTable(tableNum(NDXUnitItemMapping)).addRange(fieldNum(NDXUnitItemMapping, RefRecIdUnitOfMeasure)).value(queryValue(lUintOfMeasureConversion.FromUnitOfMeasure));
    }
    super();

}

public void init()
{
    super();
    this.query().dataSourceTable(tableNum(BOMVersion)).addRange(fieldNum(BOMVersion, Active)).value(queryValue(NoYes::Yes));
    this.query().dataSourceTable(tableNum(BOMVersion)).addRange(fieldNum(BOMVersion, Approved)).value(queryValue(NoYes::Yes));
}
